(function(root){const B=typeof module!=='undefined'?require('./battle-engine.js'):root.BattleRules,H=typeof module!=='undefined'?require('./hero-data.js'):root.HeroData;
const roster=[1,2,0,6,7,8,...H.heroes.filter(h=>h.battleId>=12).map(h=>h.battleId)],positions=[{r:7,c:3},{r:5,c:2},{r:6,c:1},{r:1,c:4},{r:2,c:3},{r:0,c:5},{r:6,c:4},{r:7,c:5},{r:6,c:2},{r:1,c:1},{r:2,c:1},{r:0,c:2}];
for(const h of H.heroes.filter(h=>h.battleId>=12))positions[h.battleId]={r:4+Math.floor((h.battleId-12)/7),c:(h.battleId-12)%7};
function arrange(p,selected){const out=p.map(v=>({...v})),taken=new Set([3,4,5,9,10,11].map(id=>out[id].r+','+out[id].c));for(const id of selected){let v=out[id],key=v.r+','+v.c;if(taken.has(key)){const free=[];for(let r=4;r<8;r++)for(let c=0;c<7;c++)if(!taken.has(r+','+c))free.push({r,c});free.sort((a,b)=>Math.abs(a.r-v.r)+Math.abs(a.c-v.c)-Math.abs(b.r-v.r)-Math.abs(b.c-v.c));out[id]=free[0];key=out[id].r+','+out[id].c}taken.add(key)}return out}
function create(p=positions,selected=[1,0,6,7,8]){if(!selected.length||selected.length>5||new Set(selected).size!==selected.length||selected.some(id=>!roster.includes(id)))throw Error('Invalid party');p=arrange(p,selected);const b=B.create(p,[6,7,8].map(id=>({...H.byBattleId[id].battle})),[{type:'archer'},{type:'sword'},{type:'mage'}]);for(const h of H.heroes.filter(h=>h.battleId>=12)){const u={...b.units[{sword:1,mage:2,archer:0}[h.battle.type]],id:h.battleId,variant:h.id,...h.stats,max:h.stats.hp,pos:{...p[h.battleId]},energy:0,cast:null,to:null};b.units.push(u)}b.sideEngagement=true;b.blockEnemyUltimates=true;let enemy=0;for(const u of b.units){if(u.team===0){u.deployed=selected.includes(u.id);if(!u.deployed)u.hp=0}else{u.enemyArt=enemy++%3;u.hp=u.max=u.max*5;u.dmg=Math.max(1,Math.round(u.dmg*.2))}}return b}
const api={create,positions,roster,arrange};if(typeof module!=='undefined')module.exports=api;else root.TestEncounter=api;
})(globalThis);
